"""Monthly stock 16 Oct - 15 Nov 2026 (4 videos a day), written by Claude.

Emre asked for four weeks of content in advance. Same rules as content_bank.py:
Qur'an references as surah:ayah, hadith only from Sahih al-Bukhari, Sahih
Muslim or Jami' at-Tirmidhi with the common (sunnah.com) numbering, history
only with well documented facts. Translations are paraphrased meaning. No verse
or hadith that the channel has already used.
"""


def E(content_type, title, hook, body, source, tags, translation=""):
    return {"content_type": content_type, "title": title, "hook": hook, "body": body,
            "translation": translation, "source": source, "tags": tags}


